  /// Every locale map (coverage tests).
  @visibleForTesting
  static Map<String, Map<String, String>> get catalog => _v;

  /// Catalog code used for [locale]: Traditional Chinese for the `Hant`
  /// script and for Taiwan, Hong Kong and Macao.
  static String localeCodeFor(Locale locale) {
    final code = locale.languageCode;
    if (code == 'zh') {
      final script = locale.scriptCode?.toLowerCase();
      final country = locale.countryCode?.toUpperCase();
      if (script == 'hant' || country == 'TW' || country == 'HK' || country == 'MO') {
        return 'zh_Hant';
      }
    }
    return code;
  }

  static String text(BuildContext context, String key) {
    final code = localeCodeFor(Localizations.localeOf(context));
    return _v[code]?[key] ?? _v['en']![key] ?? key;
  }

  static String format(
    BuildContext context,
    String key,
    Map<String, Object?> values,
  ) {
    var value = text(context, key);
    for (final item in values.entries) {
      value = value.replaceAll('{${item.key}}', item.value?.toString() ?? '');
    }
    return value;
  }
}
